@@ -101,7 +101,7 @@ export const NotificationUpdater = {
     const refreshUrl = Services.urlFormatter.formatURLPref(
       "mail.inappnotifications.url"
     );
-    if (refreshUrl === "about:blank") {
+    if (refreshUrl === "about:blank" || !refreshUrl) {
       return false;
     }
     try {
diff --git a/mail/components/inappnotifications/test/unit/test_notification_updater.js b/mail/components/inappnotifications/test/unit/test_notification_updater.js
index f6ddab161da..a503dc95402 100644
--- a/mail/components/inappnotifications/test/unit/test_notification_updater.js
+++ b/mail/components/inappnotifications/test/unit/test_notification_updater.js
@@ -106,6 +106,17 @@ add_task(async function test_fetch_noFetch() {
     "Should not fetch if there is no url configured"
   );
   Assert.ok(updateSpy.notCalled, "Should not have called the update callback");
+
+  Services.prefs.setStringPref("mail.inappnotifications.url", "about:blank");
+  const didFetchWithAboutBlank = await NotificationUpdater._fetch();
+  Assert.ok(
+    !didFetchWithAboutBlank,
+    "Should not fetch if the formatted URL is about:blank"
+  );
+  Assert.ok(
+    updateSpy.notCalled,
+    "Should not have called the update callback for about:blank"
+  );
   Services.prefs.setStringPref("mail.inappnotifications.url", url);

